import functools

def fib(n: int):
    """Return n-th Fibonacci number.
    >>> fib(10)
    55
    >>> fib(1)
    1
    >>> fib(8)
    21
    """
    if n <= 0:
        raise ValueError("n must be a positive integer")

    @functools.lru_cache(maxsize=None)
    def _fib(k: int) -> int:
        if k <= 2:
            return 1
        return _fib(k - 1) + _fib(k - 2)

    return _fib(n)
