def fizz_buzz(n: int) -> int:
    """Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13.
    >>> fizz_buzz(50)
    0
    >>> fizz_buzz(78)
    2
    >>> fizz_buzz(79)
    3
    """
    if n <= 0:
        return 0

    def count_multiples(limit: int, m: int) -> int:
        if limit < 0:
            return 0

        digits = [ord(c) - ord("0") for c in str(limit)]

        # dp[tight][started][remainder] = (count_of_numbers, total_digit_7_count)
        dp = [[[(0, 0) for _ in range(m)] for _ in range(2)] for _ in range(2)]
        dp[1][0][0] = (1, 0)

        for max_digit in digits:
            ndp = [[[(0, 0) for _ in range(m)] for _ in range(2)] for _ in range(2)]

            for tight in range(2):
                for started in range(2):
                    for rem in range(m):
                        cnt, sevens = dp[tight][started][rem]
                        if cnt == 0:
                            continue

                        upper = max_digit if tight else 9
                        for digit in range(upper + 1):
                            next_tight = 1 if tight and digit == max_digit else 0
                            next_started = 1 if started or digit != 0 else 0
                            next_rem = (rem * 10 + digit) % m if next_started else 0

                            next_sevens = sevens + (cnt if digit == 7 else 0)

