def iscube(a):
    if a == 0:
        return True

    x = abs(a)
    lo = 0
    hi = 1 << ((x.bit_length() + 2) // 3)

    while lo < hi:
        mid = (lo + hi) // 2
        if mid * mid * mid < x:
            lo = mid + 1
        else:
            hi = mid

    return lo * lo * lo == x
