def is_multiply_prime(a):
    if a < 2:
        return False

    count = 0
    n = a
    d = 2

    while d * d <= n:
        while n % d == 0:
            count += 1
            n //= d
            if count > 3:
                return False
        d += 1

    if n > 1:
        count += 1

    return count == 3
