def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    vowel_map = {
        'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w',
        'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W'
    }

    encoded_chars = []
    for char in message:
        if char in vowels:
            new_char = vowel_map[char]
        else:
            new_char = char

        if new_char.isalpha():
            if new_char.isupper():
                encoded_chars.append(new_char.lower())
            else:
                encoded_chars.append(new_char.upper())
        else:
            encoded_chars.append(new_char)

    return ''.join(encoded_chars)
