                continue

            for _ in range(s - 1):
                x = (x * x) % n
                if x == n - 1:
                    break
            else:
                return False

        return True

    largest_prime = 0
    for n in lst:
        if n > largest_prime and is_prime(n):
            largest_prime = n

    return sum(int(d) for d in str(largest_prime))
