def minPath(grid, k):
    if k <= 0 or not grid or not grid[0]:
        return []

    rows, cols = len(grid), len(grid[0])

    # The first cell of the lexicographically minimum path must contain
    # the minimum value in the grid (guaranteed to be 1 in the problem).
    r = c = 0
    current = grid[0][0]
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] < current:
                current = grid[i][j]
                r, c = i, j

    path = [current]
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))

    # Greedily extend the path by always moving to the smallest-valued
    # neighbor of the current cell.
    for _ in range(k - 1):
        best_val = None
        best_r = best_c = -1

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                val = grid[nr][nc]
                if best_val is None or val < best_val:
                    best_val = val
                    best_r, best_c = nr, nc

        if best_val is None:
            break

        path.append(best_val)
        r, c = best_r, best_c

    return path

