def minPath(grid, k):
    if k <= 0:
        return []

    n = len(grid)
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))

    min_val = None
    min_cells = []

    for i in range(n):
        for j in range(len(grid[i])):
            val = grid[i][j]
            if min_val is None or val < min_val:
                min_val = val
                min_cells = [(i, j)]
            elif val == min_val:
                min_cells.append((i, j))

    if min_val is None:
        return []

    if k == 1:
        return [min_val]

    # With a unique global minimum, the best path alternates between it
    # and its smallest neighbor.
    if len(min_cells) == 1:
        i, j = min_cells[0]
        second = None

        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < len(grid[ni]):
                val = grid[ni][nj]
                if second is None or val < second:
                    second = val

        if second is None:
            return [min_val] * k

        ans = [min_val, second] * (k // 2)
        if k % 2:
            ans.append(min_val)
        return ans

    # Fallback for grids with repeated minimum values.
    ans = [min_val]
    current = set(min_cells)

    for _ in range(1, k):
        next_min = None
        next_cells = set()

        for i, j in current:
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < len(grid[ni]):
                    val = grid[ni][nj]
                    if next_min is None or val < next_min:
                        next_min = val
                        next_cells = {(ni, nj)}
                    elif val == next_min:
                        next_cells.add((ni, nj))

        if next_min is None:
            ans.extend([ans[-1]] * (k - len(ans)))
            break

        ans.append(next_min)
        current = next_cells

    return ans
