def is_nested(string):
    # A valid nested bracket subsequence exists iff we can select
    # the subsequence "[[]]" from the input string.
    state = 0  # 0: need first '[', 1: need second '[', 2: need first ']', 3: need second ']'

    for bracket in string:
        if state == 0:
            if bracket == '[':
                state = 1
        elif state == 1:
            if bracket == '[':
                state = 2
        elif state == 2:
            if bracket == ']':
                state = 3
        elif state == 3:
            if bracket == ']':
                return True

    return False
